    describe('guessDateFromText', () => {
        it('parses ISO dates and timestamps', () => {
            expect(guessDateFromText('2023-12-03')).toEqual(new Date(2023, 11, 3));
            expect(guessDateFromText('2014-02-11T11:30:30')).toEqual(new Date(2014, 1, 11, 11, 30, 30));
        });

        it('parses month names and slash-separated dates', () => {
            expect(guessDateFromText('Jun 9, 2022')).toEqual(new Date(2022, 5, 9));
            expect(guessDateFromText('03/12/1969')).toEqual(new Date(1969, 2, 12));
            expect(guessDateFromText('2023/12/3')).toEqual(new Date(2023, 11, 3));
        });

        it('leaves invalid and empty text unset', () => {
            expect(guessDateFromText('')).toBeUndefined();
            expect(guessDateFromText('not a date')).toBeUndefined();
            expect(guessDateFromText('2023-02-30')).toBeUndefined();
            expect(guessDateFromText('2023/02/30')).toBeUndefined();
        });

